css:
.sl-article-academic {
    background-color: var(--smartlearn-bg);
    padding-block: 3rem;
}
@media (min-width: 992px) {
    .sl-article-academic { padding-block: 6rem; }
}

.sl-article-academic .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-article-academic .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-article-academic .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-article-academic .sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-article-academic .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-article-academic .sl-border { border-color: var(--smartlearn-card-border) !important; }
.sl-article-academic .sl-tracking-wide { letter-spacing: 0.1em; }

/* Logical Drop Cap (disabled in RTL to preserve cursive ligatures) */
.sl-article-academic .sl-drop-cap::first-letter {
    float: inline-start;
    font-size: 3.5rem;
    line-height: 0.8;
    padding-top: 0.2rem;
    padding-inline-end: 0.5rem;
    font-weight: 700;
    color: var(--smartlearn-primary);
}
[dir="rtl"] .sl-article-academic .sl-drop-cap::first-letter {
    float: none;
    font-size: inherit;
    line-height: inherit;
    padding: 0;
    font-weight: inherit;
    color: inherit;
}

/* CSS Columns */
.sl-article-academic .sl-academic-columns {
    text-align: start;
    column-count: 1;
    column-gap: 3rem;
    orphans: 3;
    widows: 3;
}
.sl-article-academic .sl-academic-columns h3 {
    break-after: avoid;
    page-break-after: avoid;
}
.sl-article-academic .sl-academic-columns .sl-pull-quote {
    break-inside: avoid;
    page-break-inside: avoid;
}
@media (min-width: 992px) {
    .sl-article-academic .sl-academic-columns {
        column-count: 2;
    }
}
